    color: '#ff8a3d',
    duration: 8
  },
  SPAWN_IMPATIENT: {
    id: 'SPAWN_IMPATIENT',
    title: 'Sabırsız Müşteri',
    short: 'SABIRSIZ',
    icon: '🌹',
    tag: '1–9 jeton',
    hint: 'Meydana sinirli bir müşteri girer, masaya vurur.',
    color: '#ffb020',
    duration: 10
  },
  OKEY_FIGHT: {
    id: 'OKEY_FIGHT',
    title: 'Okey Taşı Kavgası',
    short: 'OKEY KAVGASI',
    icon: '🀄',
    tag: '10–29 jeton',
    hint: 'Masadakiler ayaklanır, okey taşları havada uçar.',
    color: '#f05252',
    duration: 12
  },
  THROW_TOST_CAY: {
    id: 'THROW_TOST_CAY',
    title: 'Çay & Tost Yağmuru',
    short: 'ÇAY-TOST',
    icon: '🫖',
    tag: '30–99 jeton',
    hint: 'Altın tepsiyle tüm masalara çay ve kaşarlı tost yağar.',
