/**
 * Small transport abstraction: Socket.IO when the Node backend is present,
 * BroadcastChannel + localStorage when the game is hosted statically (the
 * published build still plays, using the local demo director).
 */
import {
  DEFAULT_CATALOG,
  DEFAULT_MAPPING,
  DEFAULT_SETTINGS,
  demoAvatar,
  demoUsers,
  normalizeMapping,
  normalizeSettings,
  resolveChatAction,
  resolveGiftAction
} from './shared/actions.js'

const CHANNEL = 'cay-ocagi-kaosu-v3'
const LS = {
  mapping: 'cay-ocagi:mapping',
  settings: 'cay-ocagi:settings'
}

const readJSON = (key, fallback) => {
  try {
    const raw = localStorage.getItem(key)
    return raw ? JSON.parse(raw) : fallback
  } catch {
    return fallback
  }
}

let demoCounter = 0
export function makeDemoUser() {
  const user = demoUsers[demoCounter % demoUsers.length]
  demoCounter += 1
  return {
    id: `${user.id}-${demoCounter}`,
    nickname: user.nickname,
    avatar: demoAvatar(user)
  }
}

/** Build an event locally, mirroring the server's simulator. */
export function buildLocalEvent(payload = {}, mapping = DEFAULT_MAPPING) {
  const user = payload.user ?? makeDemoUser()
  const kind = payload.kind ?? payload.type ?? 'chat'
  if (kind === 'like') {
    const count = Math.max(1, Number(payload.count) || 12)
    return { type: 'like', user, count, total: count, source: 'sim' }
  }
  if (kind === 'gift') {
    const coins = Math.max(1, Number(payload.coins) || 1)
    const giftId = String(payload.giftId ?? `sim-${coins}`)
    return {
      type: 'gift',
      user,
      action:
        payload.action ??
        resolveGiftAction(mapping, { giftId, coins, name: payload.giftName }) ??
        'SPAWN_IMPATIENT',
      gift: {
        id: giftId,
        name: payload.giftName ?? 'Simülasyon Hediyesi',
        coins,
        count: Math.max(1, Number(payload.count) || 1),
        repeatEnd: true
      },
      coins,
      source: 'sim'
    }
  }
  if (kind === 'join') {
    const command = payload.command === '2' ? '2' : '1'
    return {
      type: 'chat',
      text: command,
      user,
      command: resolveChatAction(mapping, command),
      source: 'sim'
    }
  }
  if (kind === 'member') return { type: 'member', user, source: 'sim' }
  return {
    type: 'chat',
    text: String(payload.text ?? '1'),
    user,
    command: resolveChatAction(mapping, payload.text ?? '1'),
    source: 'sim'
  }
}

export class Net {
  constructor({ role }) {
    this.role = role
    this.mode = 'local'
    this.socket = null
    this.channel = null
    this.handlers = new Map()
    this.mapping = normalizeMapping(readJSON(LS.mapping, DEFAULT_MAPPING))
    this.settings = normalizeSettings(readJSON(LS.settings, DEFAULT_SETTINGS))
    this.catalog = DEFAULT_CATALOG.map((g) => ({ ...g, source: 'default' }))
    this.ready = this.init()
  }

  on(event, fn) {
    if (!this.handlers.has(event)) this.handlers.set(event, new Set())
    this.handlers.get(event).add(fn)
    return () => this.handlers.get(event)?.delete(fn)
  }

  dispatch(event, payload) {
    for (const fn of this.handlers.get(event) ?? []) {
      try {
        fn(payload)
      } catch (error) {
        console.error(`[net] handler ${event}`, error)
      }
    }
    for (const fn of this.handlers.get('*') ?? []) {
      try {
        fn(event, payload)
      } catch (error) {
        console.error('[net] wildcard handler', error)
      }
    }
  }

  async init() {
    this.channel = new BroadcastChannel(CHANNEL)
    this.channel.onmessage = (message) => {
      const { event, payload } = message.data ?? {}
      if (!event) return
      if (event === 'request-state' && this.role === 'game') {
        this.dispatch('state-request', payload)
      }
      this.dispatch(event, payload)
    }
    try {
      const response = await fetch('/api/health', { signal: AbortSignal.timeout(1800) })
      const health = await response.json()
      if (!response.ok || !health?.ok) throw new Error('no backend')
      await this.loadSocketIo()
      this.connectSocket()
    } catch {
      this.mode = 'local'
      this.dispatch('mode', { mode: 'local' })
      this.dispatch('hello', {
        mapping: this.mapping,
        settings: this.settings,
        catalog: this.catalog,
        catalogSource: 'local',
        tiktok: { state: 'idle', username: '', viewers: 0, message: 'Statik demo modu' }
      })
    }
  }

  loadSocketIo() {
    return new Promise((resolve, reject) => {
      if (window.io) return resolve(window.io)
      const script = document.createElement('script')
      script.src = '/socket.io/socket.io.js'
      script.async = true
      script.onload = () => resolve(window.io)
      script.onerror = () => reject(new Error('socket.io client yüklenemedi'))
      document.head.appendChild(script)
    })
  }

  connectSocket() {
    const socket = window.io({ transports: ['websocket', 'polling'] })
    this.socket = socket
    this.mode = 'socket'
    socket.on('connect', () => {
      socket.emit('client:role', this.role)
      this.dispatch('mode', { mode: 'socket' })
    })
    socket.on('disconnect', () => this.dispatch('mode', { mode: 'offline' }))

    const forwarded = [
      'hello', 'settings', 'mapping', 'gift:catalog', 'tiktok:status', 'tiktok:log',
      'game:event', 'metrics', 'round:command', 'player:kick', 'game:trace', 'clients'
    ]
    for (const event of forwarded) {
      socket.on(event, (payload) => {
        if (event === 'hello') {
          this.mapping = normalizeMapping(payload.mapping)
          this.settings = normalizeSettings(payload.settings)
          if (Array.isArray(payload.catalog) && payload.catalog.length) this.catalog = payload.catalog
        }
        if (event === 'mapping' && payload?.mapping) {
          this.mapping = normalizeMapping(payload.mapping)
          localStorage.setItem(LS.mapping, JSON.stringify(this.mapping))
        }
        if (event === 'settings' && payload) {
          this.settings = normalizeSettings(payload)
          localStorage.setItem(LS.settings, JSON.stringify(this.settings))
        }
        if (event === 'gift:catalog' && Array.isArray(payload?.gifts)) this.catalog = payload.gifts
        this.dispatch(event, payload)
      })
    }
  }

  emit(event, payload) {
    if (this.socket?.connected) {
      this.socket.emit(event, payload)
      return
    }
    if (event.startsWith('admin:') && this.role === 'admin') {
      if (event === 'admin:simulate') {
        const evt = buildLocalEvent(payload, this.mapping)
        this.channel.postMessage({ event: 'game:event', payload: evt })
        this.dispatch('game:event', evt)
        return
      }
      if (event === 'admin:settings') {
        this.settings = normalizeSettings({ ...this.settings, ...payload })
        localStorage.setItem(LS.settings, JSON.stringify(this.settings))
        this.channel.postMessage({ event: 'settings', payload: this.settings })
        this.dispatch('settings', this.settings)
        return
      }
      if (event === 'admin:mapping' || event === 'admin:gifts') {
        this.mapping = normalizeMapping({ ...this.mapping, ...(payload.mapping ?? payload) })
        localStorage.setItem(LS.mapping, JSON.stringify(this.mapping))
        this.channel.postMessage({ event: 'mapping', payload: { mapping: this.mapping } })
        this.dispatch('mapping', { mapping: this.mapping })
        return
      }
      const map = {
        'admin:round': 'round:command',
        'admin:kick': 'player:kick'
      }
      const forward = map[event]
      if (forward) {
        this.channel.postMessage({ event: forward, payload })
        this.dispatch(forward, payload)
      }
      return
    }
    this.channel.postMessage({ event, payload })
  }

  /** Persist the assignment board (both transports ultimately reach the game). */
  saveMapping(mapping) {
    this.mapping = normalizeMapping(mapping)
    localStorage.setItem(LS.mapping, JSON.stringify(this.mapping))
    if (this.socket?.connected) {
      this.socket.emit('admin:gifts', { mapping: this.mapping })
    } else {
      this.channel.postMessage({ event: 'mapping', payload: { mapping: this.mapping } })
      this.dispatch('mapping', { mapping: this.mapping })
    }
  }

  saveSettings(patch) {
    this.settings = normalizeSettings({ ...this.settings, ...patch })
    localStorage.setItem(LS.settings, JSON.stringify(this.settings))
    if (this.socket?.connected) this.socket.emit('admin:settings', this.settings)
    else {
      this.channel.postMessage({ event: 'settings', payload: this.settings })
      this.dispatch('settings', this.settings)
    }
    return this.settings
  }

  requestState() {
    if (this.socket?.connected) this.socket.emit('admin:request')
    else this.channel.postMessage({ event: 'request-state', payload: { at: Date.now() } })
  }

  sendMetrics(metrics) {
    if (this.socket?.connected) this.socket.emit('game:metrics', metrics)
    else this.channel.postMessage({ event: 'metrics', payload: metrics })
  }

  trace(event) {
    if (this.socket?.connected) this.socket.emit('game:event-local', event)
    else this.channel.postMessage({ event: 'game:trace', payload: event })
  }
}

/**
 * Prosedürel Web Audio ses motoru — harici mp3/wav yok.
 * Tüm sesler osilatör, gürültü ve filtrelerle gerçek zamanlı sentezlenir.
 */
export class SoundEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.sfx = null
    this.ambient = null
    this.volume = 0.65
    this.muted = false
    this.unlocked = false
    this.sirenNodes = null
    this._steamTimer = null
  }

  unlock() {
    if (this.unlocked && this.ctx?.state === 'running') return true
    const Ctx = window.AudioContext || window.webkitAudioContext
    if (!Ctx) return false
    if (!this.ctx) {
      this.ctx = new Ctx()
      this.master = this.ctx.createGain()
      this.master.gain.value = this.muted ? 0 : this.volume
      this.master.connect(this.ctx.destination)

      const compressor = this.ctx.createDynamicsCompressor()
      compressor.threshold.value = -16
      compressor.knee.value = 22
      compressor.ratio.value = 5
      compressor.attack.value = 0.004
      compressor.release.value = 0.22
      compressor.connect(this.master)

      this.sfx = this.ctx.createGain()
      this.sfx.gain.value = 0.9
      this.sfx.connect(compressor)

      this.ambient = this.ctx.createGain()
      this.ambient.gain.value = 0.34
      this.ambient.connect(compressor)
      this.startAmbience()
    }
    this.ctx.resume().catch(() => {})
    this.unlocked = true
    return true
  }

  setVolume(value) {
    this.volume = Math.min(1, Math.max(0, Number(value)))
    if (this.master) this.master.gain.setTargetAtTime(this.muted ? 0 : this.volume, this.ctx.currentTime, 0.05)
  }

  setMuted(muted) {
    this.muted = Boolean(muted)
    if (this.master) this.master.gain.setTargetAtTime(this.muted ? 0 : this.volume, this.ctx.currentTime, 0.05)
  }

  now() {
    return this.ctx.currentTime
  }

  noiseBuffer(seconds = 1) {
    const length = Math.max(1, Math.floor(this.ctx.sampleRate * seconds))
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate)
    const data = buffer.getChannelData(0)
    for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1
    return buffer
  }

  startAmbience() {
    if (!this.ctx) return
    const ctx = this.ctx
    const buffer = this.noiseBuffer(2)
    const src = ctx.createBufferSource()
    src.buffer = buffer
    src.loop = true
    const lowpass = ctx.createBiquadFilter()
    lowpass.type = 'lowpass'
    lowpass.frequency.value = 480
    lowpass.Q.value = 0.4
    const gain = ctx.createGain()
    gain.gain.value = 0.1
    src.connect(lowpass).connect(gain).connect(this.ambient)
    src.start()

    const lfo = ctx.createOscillator()
    lfo.frequency.value = 0.07
    const lfoGain = ctx.createGain()
    lfoGain.gain.value = 180
    lfo.connect(lfoGain).connect(lowpass.frequency)
    lfo.start()

    // Uzak mahalle uğultusu: alçak, yumuşak bir drone.
    const drone = ctx.createOscillator()
    drone.type = 'sine'
    drone.frequency.value = 58
    const droneGain = ctx.createGain()
    droneGain.gain.value = 0.022
    drone.connect(droneGain).connect(this.ambient)
    drone.start()
  }

  tone({ freq = 440, type = 'sine', dur = 0.2, gain = 0.2, at = 0, dest = null, glide = null, curve = 'exp' }) {
    if (!this.ctx) return
    const t = this.now() + at
    const osc = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t)
    if (glide != null) {
      if (curve === 'exp') osc.frequency.exponentialRampToValueAtTime(Math.max(1, glide), t + dur)
      else osc.frequency.linearRampToValueAtTime(glide, t + dur)
    }
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.008)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    osc.connect(g).connect(dest ?? this.sfx)
    osc.start(t)
    osc.stop(t + dur + 0.05)
  }

  noise({ dur = 0.2, gain = 0.2, type = 'bandpass', freq = 1200, q = 1, at = 0, dest = null, sweep = null }) {
    if (!this.ctx) return
    const t = this.now() + at
    const src = this.ctx.createBufferSource()
    src.buffer = this.noiseBuffer(dur + 0.05)
    const filter = this.ctx.createBiquadFilter()
    filter.type = type
    filter.frequency.setValueAtTime(freq, t)
    filter.Q.value = q
    if (sweep != null) filter.frequency.exponentialRampToValueAtTime(Math.max(40, sweep), t + dur)
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(gain, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    src.connect(filter).connect(g).connect(dest ?? this.sfx)
    src.start(t)
    src.stop(t + dur + 0.08)
  }

  /** İnce belli bardağa çay kaşığı: kristal çınlama + kısa metal tık. */
  playTeaSpoon(pan = 0, at = 0) {
    if (!this.unlock()) return
    const p = this.ctx.createStereoPanner()
    p.pan.value = Math.max(-1, Math.min(1, pan))
    p.connect(this.sfx)
    this.tone({ freq: 2100 + Math.random() * 700, type: 'sine', dur: 0.5, gain: 0.16, at, dest: p, glide: 1400 })
    this.tone({ freq: 3300 + Math.random() * 900, type: 'sine', dur: 0.28, gain: 0.07, at, dest: p })
    this.noise({ dur: 0.045, gain: 0.12, type: 'highpass', freq: 5200, at, dest: p })
  }

  /** Istakaya çarpan okey taşı: tok ahşap darbe + taş tıkırtısı. */
  playOkeySlam(pan = 0, at = 0) {
    if (!this.unlock()) return
    const p = this.ctx.createStereoPanner()
    p.pan.value = Math.max(-0.8, Math.min(0.8, pan))
    p.connect(this.sfx)
    this.tone({ freq: 120, type: 'triangle', dur: 0.18, gain: 0.4, at, dest: p, glide: 52 })
    this.noise({ dur: 0.12, gain: 0.22, type: 'bandpass', freq: 1900, q: 0.8, at, dest: p })
    this.tone({ freq: 780, type: 'square', dur: 0.05, gain: 0.05, at, dest: p })
    this.noise({ dur: 0.25, gain: 0.05, type: 'highpass', freq: 4200, at: at + 0.08, dest: p })
  }

  playTeaPour(at = 0) {
    if (!this.unlock()) return
    this.noise({ dur: 0.55, gain: 0.1, type: 'bandpass', freq: 700, q: 2.2, at, sweep: 1600 })
    this.tone({ freq: 210, type: 'sine', dur: 0.2, gain: 0.06, at: at + 0.1 })
  }

  playTost() {
    if (!this.unlock()) return
    this.noise({ dur: 0.25, gain: 0.14, type: 'bandpass', freq: 2400, q: 1.4, sweep: 800 })
    this.tone({ freq: 160, type: 'sawtooth', dur: 0.12, gain: 0.06, glide: 90 })
  }

  /** Zabıta düdüğü + siren: iki tonlu, yükselen alçalan. */
  startSiren() {
    if (!this.unlock() || this.sirenNodes) return
    const ctx = this.ctx
    const t = ctx.currentTime
    const osc = ctx.createOscillator()
    const osc2 = ctx.createOscillator()
    const gain = ctx.createGain()
    const filter = ctx.createBiquadFilter()
    osc.type = 'square'
    osc2.type = 'sawtooth'
    osc.frequency.value = 660
    osc2.frequency.value = 990
    filter.type = 'bandpass'
    filter.frequency.value = 1200
    filter.Q.value = 0.7
    gain.gain.value = 0.012
    const lfo = ctx.createOscillator()
    const lfoGain = ctx.createGain()
    lfo.frequency.value = 0.72
    lfoGain.gain.value = 240
    lfo.connect(lfoGain)
    lfoGain.connect(osc.frequency)
    lfoGain.connect(osc2.frequency)
    osc.connect(filter)
    osc2.connect(filter)
    filter.connect(gain).connect(this.sfx)
    osc.start(t)
    osc2.start(t)
    lfo.start(t)
    this.sirenNodes = { osc, osc2, gain, lfo }
    // Düdük vuruşu
    this.tone({ freq: 1900, type: 'sine', dur: 0.3, gain: 0.1, glide: 2600 })
  }

  stopSiren() {
    if (!this.sirenNodes) return
    const { osc, osc2, gain, lfo } = this.sirenNodes
    const t = this.now()
    gain.gain.setTargetAtTime(0.0001, t, 0.08)
    try {
      osc.stop(t + 0.4)
      osc2.stop(t + 0.4)
      lfo.stop(t + 0.4)
    } catch {
      /* already stopped */
    }
    this.sirenNodes = null
  }

  /** Muhtar karşılama: davul vuruşları + zurna melodisi. */
  playMuhtarFanfare() {
    if (!this.unlock()) return
    const beat = 0.22
    const davul = (at, strong = 1) => {
      this.tone({ freq: 92, type: 'sine', dur: 0.24, gain: 0.32 * strong, at, glide: 46 })
      this.noise({ dur: 0.07, gain: 0.12 * strong, type: 'lowpass', freq: 900, at })
    }
    davul(0, 1.1)
    davul(beat, 0.6)
    davul(beat * 2, 0.8)
    davul(beat * 3, 0.55)
    davul(beat * 4, 1.2)
    davul(beat * 5, 0.6)
    davul(beat * 6, 0.8)
    davul(beat * 7, 0.5)

    const notes = [
      [0.0, 523.25, 0.16],
      [0.16, 659.25, 0.14],
      [0.32, 783.99, 0.2],
      [0.52, 659.25, 0.12],
      [0.66, 880.0, 0.24],
      [0.9, 783.99, 0.2],
      [1.1, 659.25, 0.16],
      [1.3, 587.33, 0.3],
      [1.6, 523.25, 0.4]
    ]
    for (const [at, freq, dur] of notes) {
      this.tone({ freq, type: 'sawtooth', dur, gain: 0.055, at, glide: freq * 0.995 })
      this.tone({ freq: freq * 2, type: 'triangle', dur: dur * 0.7, gain: 0.02, at })
    }
    // Zil / def
    this.noise({ dur: 1.4, gain: 0.05, type: 'highpass', freq: 6000, at: 0.9 })
    this.playApplause(1.7)
  }

  playApplause(at = 0) {
    if (!this.ctx) return
    for (let i = 0; i < 16; i++) {
      const t = at + Math.random() * 0.9
      this.noise({ dur: 0.06, gain: 0.028, type: 'highpass', freq: 1800 + Math.random() * 2400, at: t })
    }
  }

  playChatBlip() {
    if (!this.unlock()) return
    this.tone({ freq: 880, type: 'sine', dur: 0.07, gain: 0.05 })
    this.tone({ freq: 1320, type: 'sine', dur: 0.06, gain: 0.035, at: 0.045 })
  }

  playGiftChime(coins = 1) {
    if (!this.unlock()) return
    const base = coins >= 300 ? 392 : coins >= 100 ? 440 : coins >= 30 ? 523.25 : 659.25
    const seq = [1, 1.25, 1.5, 2]
    seq.forEach((mult, i) => {
      this.tone({ freq: base * mult, type: 'sine', dur: 0.5, gain: 0.1 - i * 0.015, at: i * 0.09 })
      this.tone({ freq: base * mult * 2.01, type: 'triangle', dur: 0.3, gain: 0.025, at: i * 0.09 })
    })
  }

  playStoveIgnite() {
    if (!this.unlock()) return
    this.noise({ dur: 0.7, gain: 0.16, type: 'bandpass', freq: 380, q: 0.7, sweep: 1600 })
    this.tone({ freq: 70, type: 'sawtooth', dur: 0.5, gain: 0.07, glide: 120 })
  }

  playWhoosh() {
    if (!this.unlock()) return
    this.noise({ dur: 0.6, gain: 0.14, type: 'bandpass', freq: 300, q: 0.6, sweep: 2400 })
  }

  playWin(kind = 'chat') {
    if (!this.unlock()) return
    const base = kind === 'chat' ? 523.25 : 392
    const notes = kind === 'chat' ? [1, 1.25, 1.5, 2] : [1, 0.75, 1.25, 1.5]
    notes.forEach((m, i) => {
      this.tone({ freq: base * m, type: 'triangle', dur: 0.7, gain: 0.12, at: i * 0.16 })
      this.tone({ freq: base * m * 0.5, type: 'sine', dur: 0.5, gain: 0.07, at: i * 0.16 })
    })
    this.playApplause(0.3)
  }

  playLose() {
    if (!this.unlock()) return
    ;[392, 370, 311, 262].forEach((f, i) =>
      this.tone({ freq: f, type: 'triangle', dur: 0.5, gain: 0.1, at: i * 0.2 })
    )
  }

  playHeartbeat() {
    if (!this.unlock()) return
    this.tone({ freq: 62, type: 'sine', dur: 0.18, gain: 0.24, glide: 40 })
    this.tone({ freq: 58, type: 'sine', dur: 0.2, gain: 0.2, at: 0.22, glide: 38 })
  }

  playCat() {
    if (!this.unlock()) return
    this.tone({ freq: 620, type: 'sine', dur: 0.24, gain: 0.03, glide: 900 })
  }
}

export const sound = new SoundEngine()

:root {
  --ink: #0b0812;
  --ink-2: #140e1c;
  --cream: #f8ecd4;
  --cream-dim: #d8c6a4;
  --amber: #ffb45c;
  --amber-deep: #e7842f;
  --brass: #d8a24a;
  --brass-dark: #8a5a23;
  --wood: #3a2313;
  --wood-2: #57351c;
  --wood-3: #774a25;
  --green: #43c98b;
  --red: #ef5b5b;
  --blue: #6a9bff;
  --shadow: 0 18px 48px rgba(0, 0, 0, .55);
  --font-ui: "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
  --font-display: "Georgia", "Times New Roman", serif;
  --font-mono: "SFMono-Regular", ui-monospace, "Cascadia Mono", "Roboto Mono", Menlo, Consolas, monospace;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  background: #07050c;
  color: var(--cream);
  font-family: var(--font-ui);
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
}

body {
  background:
    radial-gradient(90% 70% at 50% 0%, #2a1a2c 0%, #120d18 45%, #060409 100%);
}

button { font-family: inherit; }

#app {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  isolation: isolate;
}

#app::before {
  content: "";
  position: absolute;
  inset: -10%;
  background:
    radial-gradient(42% 42% at 30% 32%, rgba(255, 148, 64, .14), transparent 70%),
    radial-gradient(46% 46% at 72% 68%, rgba(90, 70, 160, .18), transparent 72%);
  filter: blur(28px);
  z-index: -1;
}

#stage {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #0a0710;
  box-shadow: 0 0 0 1px rgba(255, 200, 120, .06), var(--shadow);
}

#app[data-ratio="portrait"] #stage {
  height: 100dvh;
  width: min(100vw, calc(100dvh * 9 / 16));
  aspect-ratio: 9 / 16;
  max-height: 100dvh;
  border-radius: 2px;
}

#app[data-ratio="portrait"] #stage::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 8;
  background:
    linear-gradient(180deg, rgba(0, 0, 0, .55) 0, transparent 15%, transparent 84%, rgba(0, 0, 0, .55) 100%);
}

#app[data-ratio="landscape"] #stage {
  width: 100vw;
  height: 100dvh;
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: manipulation;
}

.grade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(20, 8, 30, .34) 0%, transparent 22%, transparent 72%, rgba(12, 6, 4, .42) 100%),
    radial-gradient(120% 90% at 50% 40%, transparent 52%, rgba(8, 4, 12, .44) 100%);
  mix-blend-mode: multiply;
  z-index: 2;
}

.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  box-shadow: inset 0 0 140px 30px rgba(3, 2, 6, .72);
  background:
    radial-gradient(130% 100% at 50% 50%, transparent 60%, rgba(4, 2, 8, .5) 100%);
}

/* ------------------------------------------------------------- top HUD */

.hud-top {
  position: absolute;
  inset: 18px 18px auto 18px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  z-index: 10;
  pointer-events: none;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 14px 9px 10px;
  border-radius: 12px;
  color: #ffe9c2;
  background:
    linear-gradient(160deg, rgba(74, 43, 23, .94), rgba(35, 20, 11, .92)),
    repeating-linear-gradient(90deg, rgba(255, 255, 255, .03) 0 2px, transparent 2px 7px);
  border: 1px solid rgba(255, 197, 111, .28);
  box-shadow:
    inset 0 1px 0 rgba(255, 226, 177, .18),
    0 10px 28px rgba(0, 0, 0, .45);
