  background:
    linear-gradient(165deg, rgba(72, 42, 22, .96) 0%, rgba(45, 26, 14, .97) 48%, rgba(28, 16, 9, .97) 100%);
  border: 1px solid rgba(255, 194, 104, .32);
  box-shadow:
    inset 0 1px 0 rgba(255, 228, 178, .18),
