.chaos-fill {
  position: absolute;
  inset: 2px auto 2px 2px;
  width: 12%;
  border-radius: 3px;
  background:
    linear-gradient(90deg, #3fbf7f 0%, #b8cc4b 38%, #ffb020 62%, #ef4d4d 100%);
  background-size: 232px 100%;
  box-shadow: 0 0 12px rgba(255, 150, 60, .4);
  transition: width .45s cubic-bezier(.3, .9, .3, 1);
}
.chaos-fill.hot { animation: hotglow .9s ease-in-out infinite; }
@keyframes hotglow {
  0%, 100% { filter: brightness(1); box-shadow: 0 0 10px rgba(255, 90, 60, .45); }
  50% { filter: brightness(1.35); box-shadow: 0 0 22px rgba(255, 90, 60, .95); }
}
.chaos-gloss {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(255, 255, 255, .22), transparent 48%);
  pointer-events: none;
}
.tick {
  position: absolute;
  top: 2px;
  bottom: 2px;
  width: 1px;
  background: rgba(0, 0, 0, .45);
}

.score-row {
  display: flex;
  justify-content: space-between;
  margin-top: 7px;
  font-size: 8px;
  letter-spacing: .12em;
  color: rgba(255, 217, 163, .68);
}
.score-row span { display: inline-flex; align-items: center; gap: 4px; }
.score-row b { color: #ffe9c6; font-size: 10px; letter-spacing: 0; }
.dot { width: 6px; height: 6px; border-radius: 50%; display: inline-block; }
.dot.chat { background: #ff8a5c; box-shadow: 0 0 6px #ff8a5c; }
.dot.cayci { background: #6ad3a0; box-shadow: 0 0 6px #6ad3a0; }

/* ------------------------------------------------------------- toasts */

.event-toasts {
  position: absolute;
  top: 92px;
  left: 18px;
  display: flex;
  flex-direction: column;
  gap: 7px;
  width: 272px;
  z-index: 12;
  pointer-events: none;
}

.toast {
  display: grid;
  grid-template-columns: 34px 1fr auto;
  align-items: center;
  gap: 9px;
  padding: 7px 10px 7px 7px;
  border-radius: 10px;
  background: linear-gradient(120deg, rgba(30, 18, 12, .9), rgba(18, 10, 16, .88));
  border: 1px solid rgba(255, 190, 100, .18);
  box-shadow: 0 8px 22px rgba(0, 0, 0, .45);
  backdrop-filter: blur(8px);
  animation: toastin .38s cubic-bezier(.2, .9, .3, 1.2);
  overflow: hidden;
  position: relative;
}
.toast::before {
  content: "";
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 3px;
  background: var(--toast-color, var(--amber));
}
.toast.out { animation: toastout .35s ease forwards; }
@keyframes toastin {
  from { opacity: 0; transform: translateX(-16px) scale(.96); }
  to { opacity: 1; transform: none; }
}
@keyframes toastout {
  to { opacity: 0; transform: translateX(-12px) scale(.97); height: 0; margin: -4px 0; padding-block: 0; }
}
.toast img {
  width: 34px;
  height: 34px;
  border-radius: 8px;
  object-fit: cover;
  background: #2a1a14;
  border: 1px solid rgba(255, 220, 170, .28);
}
.toast-copy { min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.toast-copy strong {
  font-size: 10.5px;
  font-weight: 700;
  color: #ffe9c6;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.toast-copy span {
  font-size: 9px;
  color: rgba(255, 214, 160, .66);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.toast-icon {
  font-size: 17px;
  filter: drop-shadow(0 2px 5px rgba(0, 0, 0, .5));
}

/* ---------------------------------------------------------- cinematic */

.cinematic {
  position: absolute;
  left: 50%;
  bottom: 82px;
  transform: translate(-50%, 16px);
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 320px;
  max-width: min(560px, 92%);
  padding: 10px 18px 10px 10px;
  border-radius: 16px;
  background:
    linear-gradient(120deg, rgba(48, 28, 12, .96), rgba(20, 11, 8, .95) 60%, rgba(35, 22, 8, .96));
  border: 1px solid rgba(255, 211, 120, .5);
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, .4),
    0 20px 54px rgba(0, 0, 0, .6),
    0 0 42px rgba(255, 180, 80, .18);
  opacity: 0;
  pointer-events: none;
  transition: opacity .4s ease, transform .5s cubic-bezier(.2, .9, .2, 1);
  z-index: 13;
  overflow: hidden;
}
.cinematic.show { opacity: 1; transform: translate(-50%, 0); }
.cinematic img {
  width: 58px;
  height: 58px;
  border-radius: 12px;
  object-fit: cover;
  border: 2px solid #ffd88b;
  box-shadow: 0 0 22px rgba(255, 200, 100, .35);
  background: #2a1a14;
}
.cine-copy { display: flex; flex-direction: column; line-height: 1.15; min-width: 0; }
.cine-copy span {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .24em;
  color: #ffc96e;
}
.cine-copy strong {
  font-family: var(--font-display);
  font-size: 19px;
  color: #fff0cf;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cine-copy em {
  margin-top: 2px;
  font-style: normal;
  font-size: 9.5px;
  color: rgba(255, 220, 164, .68);
}
.cine-gift { font-size: 27px; margin-left: auto; filter: drop-shadow(0 3px 8px rgba(0, 0, 0, .5)); }
.cine-thread {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, rgba(255, 209, 120, .1), transparent);
  transform: translateX(-100%);
  animation: shimmer 3.2s ease-in-out infinite;
  pointer-events: none;
}
@keyframes shimmer {
  0% { transform: translateX(-100%); }
  60%, 100% { transform: translateX(100%); }
}

/* ------------------------------------------------------------ bottom */

.hud-bottom {
  position: absolute;
  left: 50%;
  bottom: 18px;
  transform: translateX(-50%);
  width: min(620px, 76%);
  z-index: 10;
  display: flex;
  justify-content: center;
  pointer-events: none;
}

.ticker {
  display: flex;
  align-items: center;
  gap: 9px;
  max-width: 100%;
  padding: 7px 15px 7px 8px;
  border-radius: 999px;
  background: rgba(16, 10, 14, .72);
  border: 1px solid rgba(255, 200, 130, .14);
  box-shadow: 0 10px 26px rgba(0, 0, 0, .4);
  backdrop-filter: blur(10px);
  font-size: 10.5px;
  color: rgba(255, 233, 205, .82);
  white-space: nowrap;
  overflow: hidden;
}
.ticker b { color: #ffce85; }
.ticker-key {
  flex: none;
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: .16em;
  color: #3a2313;
  background: linear-gradient(180deg, #f2cd8b, #c08a3d);
}
#ticker-text {
  overflow: hidden;
  text-overflow: ellipsis;
  transition: opacity .3s ease;
}

.mini-controls {
  position: absolute;
  right: 18px;
  bottom: 16px;
  display: flex;
  align-items: center;
  gap: 7px;
  z-index: 12;
}

.demo-badge {
  padding: 4px 9px;
  border-radius: 6px;
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: .16em;
  color: rgba(255, 214, 150, .72);
  background: rgba(24, 14, 10, .68);
  border: 1px solid rgba(255, 190, 100, .16);
}
.demo-badge.live { color: #ffd0d0; border-color: rgba(255, 100, 110, .4); background: rgba(80, 14, 26, .62); }

.icon-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 30px;
  padding: 0 9px;
  border-radius: 8px;
  border: 1px solid rgba(255, 200, 130, .2);
  background: rgba(18, 11, 15, .72);
  color: rgba(255, 230, 200, .8);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .08em;
  cursor: pointer;
  backdrop-filter: blur(8px);
  transition: background .2s, color .2s, border-color .2s;
}
.icon-btn:hover { background: rgba(60, 36, 20, .85); color: #ffe9c6; border-color: rgba(255, 200, 130, .4); }
.icon-btn.off { color: rgba(255, 255, 255, .34); }

.sound-hint {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  padding: 9px 16px;
  border-radius: 999px;
  background: rgba(12, 8, 14, .82);
  border: 1px solid rgba(255, 200, 120, .22);
  color: #ffe6bd;
  font-size: 11px;
  z-index: 20;
  pointer-events: none;
  transition: opacity .5s ease;
}
.sound-hint.hide { opacity: 0; }

/* ------------------------------------------------------------- overlay */

.round-overlay {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: grid;
  place-items: center;
  background:
    radial-gradient(70% 60% at 50% 46%, rgba(30, 14, 30, .62), rgba(5, 3, 8, .9));
  backdrop-filter: blur(5px);
  animation: fadein .5s ease;
}
.round-overlay[hidden] { display: none; }
@keyframes fadein { from { opacity: 0; } }

.verdict {
  text-align: center;
  padding: 30px 44px 26px;
  border-radius: 22px;
  background:
    linear-gradient(165deg, rgba(60, 34, 18, .94), rgba(24, 14, 10, .96));
  border: 1px solid rgba(255, 205, 120, .4);
  box-shadow: 0 0 0 6px rgba(255, 200, 110, .05), 0 30px 90px rgba(0, 0, 0, .7);
  animation: verdictin .6s cubic-bezier(.16, .9, .22, 1.1);
  max-width: min(560px, 88vw);
}
@keyframes verdictin {
  from { opacity: 0; transform: translateY(18px) scale(.94); }
  to { opacity: 1; transform: none; }
}
.verdict-kicker {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .32em;
  color: rgba(255, 210, 140, .62);
}
.verdict h2 {
  margin: 7px 0 5px;
  font-family: var(--font-display);
  font-size: clamp(30px, 6.2vw, 60px);
  line-height: 1;
  letter-spacing: .01em;
  color: #ffe3a8;
  text-shadow: 0 2px 0 #7b4318, 0 0 40px rgba(255, 180, 70, .35);
}
.verdict p { margin: 6px 0 16px; font-size: 12px; color: rgba(255, 231, 200, .7); }
.verdict-stats { display: flex; justify-content: center; gap: 26px; font-size: 8.5px; letter-spacing: .16em; color: rgba(255, 214, 155, .55); }
.verdict-stats b { display: block; margin-top: 3px; font-size: 18px; letter-spacing: 0; color: #ffd88f; }
.verdict-next { margin-top: 16px; font-size: 10px; color: rgba(255, 226, 190, .58); }
.verdict-next b { color: #ffce85; }

.confetti { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.confetti i {
  position: absolute;
  top: -12px;
  width: 7px;
  height: 12px;
  border-radius: 2px;
  opacity: .9;
  animation: confall linear forwards;
}
@keyframes confall {
  to { transform: translate3d(var(--dx, 0), 110vh, 0) rotate(720deg); opacity: .2; }
}

/* ---------------------------------------------------------------- boot */

#boot {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  background:
    radial-gradient(60% 45% at 50% 42%, #3a2318 0%, #170d12 50%, #07050a 100%);
  transition: opacity .7s ease, visibility .7s;
}
#boot.hide { opacity: 0; visibility: hidden; }
.boot-cup { position: relative; margin-bottom: 4px; filter: drop-shadow(0 16px 28px rgba(0, 0, 0, .5)); }
.steam {
  position: absolute;
  top: -2px;
  left: 50%;
  width: 8px;
  height: 26px;
  border-radius: 999px;
  background: linear-gradient(180deg, transparent, rgba(255, 238, 210, .5));
  filter: blur(4px);
  animation: steamup 2.6s ease-in-out infinite;
}
.steam.s1 { margin-left: -16px; animation-delay: 0s; }
.steam.s2 { margin-left: -2px; animation-delay: .7s; }
.steam.s3 { margin-left: 13px; animation-delay: 1.3s; }
@keyframes steamup {
  0% { opacity: 0; transform: translateY(14px) scaleY(.5); }
  35% { opacity: .8; }
  100% { opacity: 0; transform: translateY(-22px) scaleY(1.4); }
}
#boot h1 {
  margin: 4px 0 0;
  font-family: var(--font-display);
  font-size: clamp(22px, 4.6vw, 40px);
  letter-spacing: .06em;
  color: #ffe5b6;
  text-shadow: 0 2px 0 #6c3b17, 0 0 40px rgba(255, 180, 80, .3);
}
#boot p { margin: 0; font-size: 11px; letter-spacing: .18em; color: rgba(255, 219, 166, .5); text-transform: uppercase; }
.boot-bar { width: 160px; height: 3px; margin-top: 12px; border-radius: 999px; background: rgba(255, 220, 170, .12); overflow: hidden; }
.boot-bar i { display: block; width: 40%; height: 100%; border-radius: inherit; background: linear-gradient(90deg, #ff9f4a, #ffe0a6); animation: bootslide 1.3s ease-in-out infinite; }
@keyframes bootslide { 0% { transform: translateX(-110%); } 100% { transform: translateX(360%); } }

/* ---------------------------------------------------------------- fatal */

.fatal {
  position: absolute;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  text-align: center;
  background: rgba(6, 4, 10, .92);
  padding: 20px;
}
.fatal[hidden] { display: none; }
.fatal h1 { font-family: var(--font-display); color: #ffd699; font-size: 24px; margin: 0 0 6px; }
.fatal p { color: rgba(255, 230, 200, .65); font-size: 12px; margin: 0 0 18px; }
.fatal button {
  padding: 9px 18px;
  border-radius: 8px;
  border: 1px solid rgba(255, 200, 120, .4);
  background: #3a2313;
  color: #ffe5b6;
  font-weight: 700;
  cursor: pointer;
}

/* ------------------------------------------------------------ portrait */

#app[data-ratio="portrait"] .hud-top {
  inset: max(14px, env(safe-area-inset-top)) 12px auto 12px;
}
#app[data-ratio="portrait"] .brand { padding: 7px 10px 7px 8px; gap: 7px; }
#app[data-ratio="portrait"] .brand-mark { width: 30px; height: 30px; }
#app[data-ratio="portrait"] .brand-mark svg { width: 24px; height: 24px; }
#app[data-ratio="portrait"] .brand-text strong { font-size: 11px; letter-spacing: .05em; }
#app[data-ratio="portrait"] .brand-text em { font-size: 6.5px; letter-spacing: .24em; }
#app[data-ratio="portrait"] .live-cluster { padding: 3px; }
#app[data-ratio="portrait"] .live-pill { font-size: 8px; padding: 3px 7px 3px 5px; }
#app[data-ratio="portrait"] .viewers { font-size: 9px; padding-right: 4px; }
#app[data-ratio="portrait"] .viewers b { font-size: 10px; }

#app[data-ratio="portrait"] .scoreboard {
  top: 64px;
  right: 12px;
  width: 188px;
  padding: 9px 11px 9px;
}
#app[data-ratio="portrait"] .timer { font-size: 27px; }
#app[data-ratio="portrait"] .chaos-track { height: 11px; }
#app[data-ratio="portrait"] .score-row { font-size: 7px; }

#app[data-ratio="portrait"] .event-toasts { top: 178px; left: 10px; width: 224px; }
#app[data-ratio="portrait"] .toast { grid-template-columns: 28px 1fr auto; padding: 5px 8px 5px 5px; }
#app[data-ratio="portrait"] .toast img { width: 28px; height: 28px; }

#app[data-ratio="portrait"] .hud-bottom {
  width: calc(100% - 128px);
  bottom: max(16px, env(safe-area-inset-bottom));
  left: 12px;
  transform: none;
}
#app[data-ratio="portrait"] .ticker {
  width: 100%;
  font-size: 8.5px;
  padding: 5px 10px 5px 5px;
  gap: 6px;
}
#app[data-ratio="portrait"] .ticker-key { display: none; }

#app[data-ratio="portrait"] .mini-controls {
  right: 10px;
  bottom: max(14px, env(safe-area-inset-bottom));
  gap: 5px;
}
#app[data-ratio="portrait"] .demo-badge { display: none; }
#app[data-ratio="portrait"] .icon-btn { height: 27px; padding: 0 7px; font-size: 8px; }
#app[data-ratio="portrait"] .icon-btn svg { width: 15px; height: 15px; }

#app[data-ratio="portrait"] .cinematic {
  bottom: 64px;
  min-width: 0;
  width: calc(100% - 24px);
  padding: 8px 12px 8px 8px;
  gap: 9px;
}
#app[data-ratio="portrait"] .cinematic img { width: 42px; height: 42px; }
#app[data-ratio="portrait"] .cine-copy strong { font-size: 15px; }
#app[data-ratio="portrait"] .cine-copy em { font-size: 8px; }
#app[data-ratio="portrait"] .cine-gift { font-size: 21px; }

#app[data-ratio="portrait"] .verdict { padding: 24px 22px 20px; }
#app[data-ratio="portrait"] .verdict h2 { font-size: clamp(26px, 9vw, 42px); }
#app[data-ratio="portrait"] .verdict p { font-size: 10.5px; }

@media (max-width: 640px) {
  .hud-top { inset: 12px 10px auto 10px; }
  .event-toasts { width: 218px; }
}

