    radial-gradient(60% 36% at 0 30%, rgba(120, 80, 200, .10), transparent 70%),
    var(--bg);
  font-family: var(--ui);
  -webkit-font-smoothing: antialiased;
}

button, input, select { font-family: inherit; }
button { cursor: pointer; }
a { color: inherit; }

.shell {
  display: grid;
  grid-template-columns: 238px minmax(0, 1fr);
  min-height: 100vh;
}

/* --------------------------------------------------------------- sidebar */

.sidebar {
  position: sticky;
  top: 0;
  align-self: start;
  height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 26px;
  padding: 22px 18px;
  background:
    linear-gradient(180deg, rgba(32, 20, 14, .92), rgba(12, 8, 16, .96)),
    repeating-linear-gradient(90deg, rgba(255, 255, 255, .018) 0 2px, transparent 2px 8px);
  border-right: 1px solid var(--line);
  z-index: 5;
}

.mark {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
}
.mark-cup {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 11px;
  background: radial-gradient(circle at 35% 28%, #ffd899, #b7742a 72%);
  box-shadow: inset 0 0 0 1px rgba(58, 35, 19, .6), 0 6px 14px rgba(0, 0, 0, .4);
}
.mark strong {
  display: block;
  font-size: 14px;
  letter-spacing: .1em;
  font-family: Georgia, serif;
}
.mark em {
  display: block;
  margin-top: 4px;
  font-style: normal;
  font-size: 8.5px;
  letter-spacing: .26em;
  color: rgba(255, 210, 145, .62);
}

.nav { display: flex; flex-direction: column; gap: 3px; }
.nav a {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 11px;
  border-radius: 9px;
  text-decoration: none;
  color: var(--dim);
  font-size: 13px;
  border: 1px solid transparent;
  transition: background .15s, color .15s, border-color .15s;
}
.nav a i { font-style: normal; width: 16px; text-align: center; font-size: 12px; opacity: .8; }
.nav a:hover { color: var(--cream); background: rgba(255, 180, 92, .06); }
.nav a.active {
  color: #ffe6bd;
  background: linear-gradient(90deg, rgba(255, 180, 92, .14), rgba(255, 180, 92, .02));
  border-color: rgba(255, 180, 92, .18);
}

.side-foot { margin-top: auto; display: flex; flex-direction: column; gap: 10px; }
.conn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 10px;
  border-radius: 9px;
  background: rgba(255, 255, 255, .025);
  border: 1px solid var(--line);
  font-size: 11.5px;
  color: var(--dim);
}
.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--dim-2);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, .03);
}
.dot.ok { background: var(--green); box-shadow: 0 0 0 3px rgba(67, 201, 139, .14), 0 0 12px rgba(67, 201, 139, .7); }
.dot.warn { background: var(--amber); box-shadow: 0 0 0 3px rgba(255, 180, 92, .14); }
.dot.bad { background: var(--red); box-shadow: 0 0 0 3px rgba(239, 91, 91, .14); }
.tiny { font-size: 10px; letter-spacing: .08em; color: var(--dim-2); text-align: center; }

/* ------------------------------------------------------------------ main */

.main {
  min-width: 0;
  padding: 24px clamp(16px, 2.6vw, 34px) 30px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.topbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding-bottom: 4px;
}
.topbar h1 {
  margin: 0;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(24px, 2.6vw, 34px);
  letter-spacing: .01em;
  font-weight: 600;
}
.sub { margin: 6px 0 0; color: var(--dim); font-size: 13px; }
.top-pills { display: flex; gap: 8px; flex-wrap: wrap; }
.pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 12px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, .03);
  font-size: 11.5px;
  color: var(--dim);
  white-space: nowrap;
}
.pill b { color: var(--cream); font-family: var(--mono); font-size: 11.5px; }
.pill.live { color: #ffd8a8; border-color: rgba(255, 180, 92, .28); background: rgba(255, 180, 92, .08); }
.pill.live i { width: 7px; height: 7px; border-radius: 50%; background: var(--amber); animation: pulse 1.8s infinite; }
.pill.live.on { color: #b7f4d6; border-color: rgba(67, 201, 139, .3); background: rgba(67, 201, 139, .1); }
.pill.live.on i { background: var(--green); }

@keyframes pulse { 50% { opacity: .25; transform: scale(.75); } }

/* ----------------------------------------------------------------- cards */

.card {
  position: relative;
  padding: 18px;
  border-radius: 15px;
  border: 1px solid var(--line);
  background:
    linear-gradient(165deg, rgba(255, 220, 170, .035), transparent 45%),
    var(--panel);
  box-shadow: 0 1px 0 rgba(255, 255, 255, .025) inset, var(--shadow);
  scroll-margin-top: 18px;
}
.card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
}
.card h2 { margin: 0; font-size: 15px; letter-spacing: .02em; font-weight: 600; }
.card-head p { margin: 5px 0 0; font-size: 12px; color: var(--dim); max-width: 58ch; }
.tag {
  flex: none;
  padding: 5px 9px;
  border-radius: 7px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, .03);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: .08em;
  color: var(--dim);
  white-space: nowrap;
}
.tag.ok { color: #a8f0cd; border-color: rgba(67, 201, 139, .3); background: rgba(67, 201, 139, .08); }
.tag.warn { color: #ffd8a8; border-color: rgba(255, 180, 92, .3); background: rgba(255, 180, 92, .08); }

.status {
  flex: none;
  padding: 7px 11px;
  border-radius: 8px;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: .1em;
  color: var(--dim);
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, .025);
}
.status.connected { color: #a8f0cd; border-color: rgba(67, 201, 139, .34); background: rgba(67, 201, 139, .08); }
.status.error { color: #ffb3b3; border-color: rgba(239, 91, 91, .34); background: rgba(239, 91, 91, .08); }
.status.connecting { color: #ffd8a8; border-color: rgba(255, 180, 92, .34); background: rgba(255, 180, 92, .08); }

/* --------------------------------------------------------------- connect */

.connect-form { display: flex; gap: 9px; align-items: flex-end; flex-wrap: wrap; }
.connect-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 22px;
  margin-top: 13px;
  padding-top: 12px;
  border-top: 1px dashed var(--line);
  font-size: 11.5px;
  color: var(--dim);
}
.connect-meta b { color: var(--cream); font-weight: 500; }

.field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.field > span {
  font-size: 10px;
  letter-spacing: .09em;
  text-transform: uppercase;
  color: var(--dim-2);
}
.field.grow { flex: 1 1 240px; }
input[type="text"], input[type="search"], select {
  width: 100%;
  padding: 9px 11px;
  border-radius: 9px;
  border: 1px solid var(--line-strong);
  background: #0c0812;
  color: var(--cream);
  font-size: 12.5px;
  outline: none;
  transition: border-color .15s, box-shadow .15s;
}
input:focus, select:focus {
  border-color: rgba(255, 180, 92, .52);
  box-shadow: 0 0 0 3px rgba(255, 180, 92, .1);
}
input::placeholder { color: #5e5360; }
select { appearance: none; background-image: linear-gradient(45deg, transparent 50%, var(--dim) 50%), linear-gradient(135deg, var(--dim) 50%, transparent 50%); background-position: calc(100% - 15px) 50%, calc(100% - 10px) 50%; background-size: 5px 5px, 5px 5px; background-repeat: no-repeat; padding-right: 28px; }
select option { background: #140e1b; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 9px 14px;
  border-radius: 9px;
  border: 1px solid var(--line-strong);
  background: linear-gradient(180deg, rgba(255, 255, 255, .06), rgba(255, 255, 255, .015));
  color: var(--cream);
  font-size: 12px;
  font-weight: 500;
  transition: transform .12s, border-color .15s, background .15s, opacity .15s;
  white-space: nowrap;
}
.btn:hover { border-color: rgba(255, 180, 92, .45); background: rgba(255, 180, 92, .08); }
.btn:active { transform: translateY(1px); }
.btn.primary {
  color: #24160a;
  border-color: #ffca85;
  background: linear-gradient(180deg, #ffcf92, #e7903c);
  font-weight: 650;
  box-shadow: 0 6px 18px rgba(231, 144, 60, .22);
}
.btn.primary:hover { background: linear-gradient(180deg, #ffdbaa, #f09b46); }
.btn.danger { color: #ffc4c4; border-color: rgba(239, 91, 91, .32); background: rgba(239, 91, 91, .07); }
.btn.danger:hover { background: rgba(239, 91, 91, .15); border-color: rgba(239, 91, 91, .5); }
.btn.ghost { background: rgba(255, 255, 255, .02); }
.btn.small { padding: 5px 9px; font-size: 10.5px; border-radius: 7px; }
.btn.wide { width: 100%; }
.btn:disabled { opacity: .4; cursor: not-allowed; transform: none; }

/* ------------------------------------------------------------------ KPIs */

.kpis {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 10px;
}
.kpi {
  position: relative;
  overflow: hidden;
  padding: 13px 14px 12px;
  border-radius: 13px;
  border: 1px solid var(--line);
  background: linear-gradient(165deg, rgba(255, 255, 255, .035), rgba(255, 255, 255, .008)), var(--panel);
}
.kpi::after {
  content: "";
  position: absolute;
  inset: auto 0 0 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, .12), transparent);
}
.kpi span { display: block; font-size: 9.5px; letter-spacing: .1em; text-transform: uppercase; color: var(--dim-2); }
.kpi b { display: block; margin: 7px 0 3px; font-family: var(--mono); font-size: clamp(18px, 2vw, 23px); font-weight: 600; letter-spacing: -.02em; }
.kpi em { display: block; font-style: normal; font-size: 10.5px; color: var(--dim); }
.kpi.amber b { color: #ffd49a; }
.kpi.red b { color: #ff9d9d; }
.kpi.blue b { color: #a9c4ff; }
.kpi.green b { color: #9bf0c8; }
.bar { display: block; height: 4px; border-radius: 99px; background: rgba(255, 255, 255, .08); overflow: hidden; }
.bar u {
  display: block;
  height: 100%;
  width: 0;
  border-radius: 99px;
  background: linear-gradient(90deg, #ffb45c, #ef5b5b);
  transition: width .35s ease;
}

/* --------------------------------------------------------------- columns */

.columns {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.16fr);
  gap: 16px;
  align-items: start;
}
.col { display: flex; flex-direction: column; gap: 16px; min-width: 0; }

.btn-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.sim-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 7px; }
.sim-grid .btn { padding: 9px 6px; font-size: 11px; }

/* --------------------------------------------------------------- mapping */

.mini-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 9px; }
.mini-grid .check { grid-column: span 3; }
.sub-title {
  margin: 16px 0 8px;
  font-size: 10px;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--dim-2);
  font-weight: 600;
}
.ranges { display: flex; flex-direction: column; gap: 6px; }
.range-row {
  display: grid;
  grid-template-columns: 1fr 18px 1fr minmax(0, 1.9fr);
  align-items: center;
  gap: 7px;
  padding: 6px;
  border-radius: 9px;
  border: 1px solid rgba(255, 255, 255, .05);
  background: rgba(0, 0, 0, .16);
}
.range-row input { padding: 6px 8px; font-family: var(--mono); font-size: 11.5px; text-align: center; }
.range-row select { padding: 6px 24px 6px 8px; font-size: 11px; }
.range-sep { color: var(--dim-2); text-align: center; font-size: 11px; }

.override-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 14px; flex-wrap: wrap; }
.override-head .sub-title { margin-bottom: 0; }
.field.search { flex: 0 1 180px; }
.hint { margin: 7px 0 10px; font-size: 10.5px; color: var(--dim-2); line-height: 1.5; }

.gift-table {
  max-height: 322px;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(0, 0, 0, .16);
  scrollbar-width: thin;
  scrollbar-color: #3a2d3f transparent;
}
.gift-row {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr) 54px minmax(0, 1.25fr);
  align-items: center;
  gap: 8px;
  padding: 7px 9px;
  border-bottom: 1px solid rgba(255, 255, 255, .04);
}
.gift-row:last-child { border-bottom: 0; }
.gift-row:hover { background: rgba(255, 180, 92, .035); }
.gift-icon {
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  border-radius: 7px;
  background: rgba(255, 255, 255, .05);
  border: 1px solid rgba(255, 255, 255, .06);
  font-size: 14px;
  overflow: hidden;
}
.gift-icon img { width: 100%; height: 100%; object-fit: cover; }
.gift-name { min-width: 0; font-size: 11.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.gift-coins { font-family: var(--mono); font-size: 10px; color: #ffcf92; text-align: right; }
.gift-row select { padding: 5px 22px 5px 7px; font-size: 10.5px; background-color: #0c0812; }
.gift-row select.changed { border-color: rgba(255, 180, 92, .5); }

.save-row { display: flex; align-items: center; gap: 9px; margin-top: 13px; flex-wrap: wrap; }
.save-note { font-size: 10.5px; color: var(--green); min-height: 14px; }
.save-note.warn { color: var(--amber); }

/* --------------------------------------------------------------- sliders */

.sliders { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 11px 16px; margin-bottom: 14px; }
.slider { display: flex; flex-direction: column; gap: 5px; }
.slider label { display: flex; justify-content: space-between; gap: 8px; font-size: 10.5px; color: var(--dim); }
.slider output { font-family: var(--mono); font-size: 10.5px; color: #ffd49a; }
input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 4px;
  border-radius: 99px;
  background: linear-gradient(90deg, rgba(255, 180, 92, .65) var(--fill, 50%), rgba(255, 255, 255, .08) var(--fill, 50%));
  outline: none;
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: #ffd49a;
  border: 2px solid #4a2d13;
  box-shadow: 0 0 0 3px rgba(255, 180, 92, .12);
  cursor: grab;
}
input[type="range"]::-moz-range-thumb {
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: #ffd49a;
  border: 2px solid #4a2d13;
  cursor: grab;
}
.check { display: flex; align-items: center; gap: 8px; font-size: 11.5px; color: var(--dim); }
.check input { accent-color: var(--amber-deep); width: 14px; height: 14px; }

/* --------------------------------------------------------------- players */

.players { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 7px; max-height: 330px; overflow: auto; }
.player {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  padding: 6px 7px;
  border-radius: 9px;
  border: 1px solid rgba(255, 255, 255, .05);
  background: rgba(0, 0, 0, .16);
}
.player img, .player .ph {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  object-fit: cover;
  background: #2a201d;
  display: grid;
  place-items: center;
  font-size: 13px;
}
.player-meta { min-width: 0; }
.player-name { font-size: 11.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.player-sub { font-size: 9.5px; color: var(--dim-2); margin-top: 2px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.player .btn { padding: 4px 7px; font-size: 10px; border-radius: 6px; }
.empty { grid-column: 1 / -1; margin: 0; padding: 18px; text-align: center; color: var(--dim-2); font-size: 11.5px; }

/* ------------------------------------------------------------------- log */

.log-card { scroll-margin-top: 18px; }
.log-tools { display: flex; align-items: center; gap: 7px; flex-wrap: wrap; }
.log {
  list-style: none;
  margin: 0;
  padding: 0;
  height: 268px;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #08060c;
  font-family: var(--mono);
  font-size: 11px;
  scrollbar-width: thin;
  scrollbar-color: #3a2d3f transparent;
}
.log li {
  display: grid;
  grid-template-columns: 66px 58px minmax(0, 1fr);
  gap: 9px;
  padding: 6px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, .035);
  line-height: 1.45;
}
.log li:last-child { border-bottom: 0; }
.log time { color: #5e5360; }
.log .kind { color: var(--amber); text-transform: uppercase; font-size: 9px; letter-spacing: .05em; padding-top: 1px; }
.log li.ok .kind { color: var(--green); }
.log li.error .kind { color: var(--red); }
.log li.warn .kind { color: var(--amber); }
.log li.gift .kind { color: #ffd166; }
.log li.chat .kind { color: var(--violet); }
.log li.like .kind { color: #ff8a8a; }
.log li.member .kind { color: #67e8f9; }
.log li.trace .kind { color: #9ba7b8; }
.log li .msg { color: #b9acb4; overflow-wrap: anywhere; }
.log li .msg b { color: var(--cream); font-weight: 500; }
.log li .msg em { font-style: normal; color: #ffd49a; }

/* ----------------------------------------------------------------- misc */

.foot {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  padding: 6px 2px 0;
  font-size: 10px;
  letter-spacing: .04em;
  color: var(--dim-2);
}

.toast-stack {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 50;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: min(340px, calc(100vw - 36px));
}
.toast {
  padding: 10px 13px;
  border-radius: 10px;
  border: 1px solid var(--line-strong);
  background: rgba(20, 14, 27, .96);
  box-shadow: var(--shadow);
  font-size: 11.5px;
  line-height: 1.45;
  animation: toast-in .2s ease;
}
.toast.ok { border-color: rgba(67, 201, 139, .34); color: #c9f7e1; }
.toast.bad { border-color: rgba(239, 91, 91, .34); color: #ffd0d0; }
@keyframes toast-in { from { opacity: 0; transform: translateY(8px); } }

/* -------------------------------------------------------------- responsive */

@media (max-width: 1120px) {
  .kpis { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .columns { grid-template-columns: minmax(0, 1fr); }
}

@media (max-width: 820px) {
  .shell { grid-template-columns: minmax(0, 1fr); }
  .sidebar {
    position: sticky;
    top: 0;
    height: auto;
    flex-direction: row;
    align-items: center;
    gap: 14px;
    padding: 10px 14px;
    overflow-x: auto;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }
  .nav { flex-direction: row; gap: 2px; }
  .nav a { padding: 7px 9px; font-size: 11.5px; white-space: nowrap; }
  .nav a i { display: none; }
  .side-foot { margin: 0 0 0 auto; flex-direction: row; align-items: center; }
  .side-foot .conn, .side-foot .tiny { display: none; }
  .side-foot .btn { padding: 7px 10px; font-size: 11px; }
  .main { padding: 16px 12px 22px; }
  .kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .sim-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 540px) {
  .mark em { display: none; }
  .mark strong { font-size: 12.5px; }
  .topbar h1 { font-size: 22px; }
  .top-pills .pill:nth-child(3) { display: none; }
  .mini-grid, .sliders { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .mini-grid .check { grid-column: span 2; }
  .players { grid-template-columns: minmax(0, 1fr); }
  .btn-grid { grid-template-columns: minmax(0, 1fr); }
  .range-row { grid-template-columns: 1fr 12px 1fr; }
  .range-row select { grid-column: 1 / -1; }
  .card { padding: 14px; }
  .gift-row { grid-template-columns: 27px minmax(0, 1fr) 46px; }
  .gift-row select { grid-column: 1 / -1; }
  .log li { grid-template-columns: 52px 48px minmax(0, 1fr); gap: 6px; }
}

@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; scroll-behavior: auto !important; }
}

/**
 * Çay Ocağı Kaosu — admin dashboard controller.
 *
 * Talks to the same Socket.IO backend as the game through the shared Net
 * transport. When the backend is absent it still renders a usable local demo
 * and mirrors changes over BroadcastChannel.
 */
import { Net } from './net.js'
import {
  ACTIONS,
  ACTION_ORDER,
  DEFAULT_CATALOG,
  DEFAULT_MAPPING,
  DEFAULT_SETTINGS,
  demoAvatar,
  normalizeMapping,
  normalizeSettings
} from './shared/actions.js'

const $ = (id) => document.getElementById(id)
const esc = (value) =>
  String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]))
const clone = (value) => JSON.parse(JSON.stringify(value))
const pad = (n) => String(n).padStart(2, '0')
const formatClock = (date = new Date()) => `${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`
const formatTimer = (seconds) => {
  const total = Math.max(0, Math.ceil(Number(seconds) || 0))
  return `${pad(Math.floor(total / 60))}:${pad(total % 60)}`
}
const compact = (n) => {
  const num = Number(n) || 0
  if (num >= 1_000_000) return `${(num / 1_000_000).toFixed(1)}M`
  if (num >= 10_000) return `${Math.round(num / 1000)}B`
  return new Intl.NumberFormat('tr-TR').format(Math.round(num))
}

const COMMAND_ACTIONS = ['JOIN_CUSTOMER', 'JOIN_APPRENTICE']
const GIFT_ACTIONS = ACTION_ORDER
const ALL_ACTIONS = [...ACTION_ORDER, 'JOIN_CUSTOMER', 'JOIN_APPRENTICE']

const net = new Net({ role: 'admin' })

let savedMapping = normalizeMapping(net.mapping)
let draft = clone(savedMapping)
let settings = normalizeSettings(net.settings)
let catalog = Array.isArray(net.catalog) && net.catalog.length ? net.catalog : DEFAULT_CATALOG
let metrics = null
let tiktok = { state: 'idle', username: '', roomId: '', viewers: 0, message: '', eventCount: 0 }
let clients = 0
let dirty = false
let settingsEchoUntil = 0
let giftFilter = ''
let logPaused = false
let logCount = 0
let settingsTimer = 0

/* ------------------------------------------------------------------ init */

renderActionSelects()
renderRanges()
renderGiftTable()
renderSliders()
renderSettings()
renderMetrics()
renderConnection()
startClock()

net.on('hello', (hello = {}) => {
  if (hello.mapping && !dirty) {
    savedMapping = normalizeMapping(hello.mapping)
    draft = clone(savedMapping)
    renderActionSelects()
    renderRanges()
    renderGiftTable()
  }
  if (hello.settings && Date.now() >= settingsEchoUntil) {
    settings = normalizeSettings(hello.settings)
    renderSliders()
    renderSettings()
  }
  if (Array.isArray(hello.catalog) && hello.catalog.length) {
    catalog = hello.catalog
    renderGiftTable()
  }
  if (hello.tiktok) {
    tiktok = hello.tiktok
    renderConnection()
  }
  if (Number.isFinite(hello.clients)) {
    clients = hello.clients
    renderClients()
  }
  if (hello.metrics) {
    metrics = hello.metrics
    renderMetrics()
  }
})

net.on('mode', ({ mode } = {}) => {
  const local = mode === 'local'
  $('side-dot').className = `dot ${local ? 'warn' : mode === 'offline' ? 'bad' : 'ok'}`
  $('side-mode').textContent = local ? 'Yerel demo modu' : mode === 'offline' ? 'Sunucu bağlantısı kesildi' : 'Sunucuya bağlı'
})

net.on('mapping', ({ mapping } = {}) => {
  if (!mapping) return
  if (dirty) {
    setSaveNote('Sunucudan yeni kurallar geldi — senin taslağın korunuyor.', true)
    return
  }
  savedMapping = normalizeMapping(mapping)
  draft = clone(savedMapping)
  renderActionSelects()
  renderRanges()
  renderGiftTable()
  setSaveNote('Kurallar güncellendi.')
})

net.on('settings', (incoming) => {
  if (!incoming || Date.now() < settingsEchoUntil) return
  settings = normalizeSettings(incoming)
  renderSliders()
  renderSettings()
})

net.on('gift:catalog', (payload = {}) => {
  if (Array.isArray(payload.gifts) && payload.gifts.length) {
    catalog = payload.gifts
    renderGiftTable()
  }
})

net.on('metrics', (incoming) => {
  metrics = incoming
  renderMetrics()
})

net.on('clients', ({ count } = {}) => {
  clients = Number(count) || 0
  renderClients()
})

net.on('tiktok:status', (status) => {
  tiktok = status ?? tiktok
  renderConnection()
})

net.on('tiktok:log', ({ level, message } = {}) => {
  addLog(level === 'error' ? 'error' : level === 'warn' ? 'warn' : 'ok', 'bağlantı', message)
})

net.on('game:event', (event = {}) => logGameEvent(event))
net.on('game:trace', (event = {}) => {
  const action = event.action ? ACTIONS[event.action]?.title : null
  addLog('trace', event.type ?? 'oyun', [event.user?.nickname, action ?? event.message ?? event.text].filter(Boolean).join(' · '))
})

/* ------------------------------------------------------------------ clock */

function startClock() {
  const tick = () => {
    $('pill-clock').textContent = formatClock()
  }
  tick()
  setInterval(tick, 1000)
}

/* ------------------------------------------------------------- connection */

function renderConnection() {
  const state = tiktok?.state ?? 'idle'
  const labels = { idle: 'BEKLEMEDE', connecting: 'BAĞLANIYOR', connected: 'CANLI', error: 'HATA' }
  const el = $('tiktok-state')
  el.textContent = labels[state] ?? String(state).toUpperCase()
  el.className = `status ${state}`

  $('room-id').textContent = tiktok?.roomId ? String(tiktok.roomId).slice(-12) : '—'
  $('event-count').textContent = compact(tiktok?.eventCount ?? 0)
  $('tiktok-message').textContent = tiktok?.message || 'Hazır'
  $('username').value = tiktok?.username || $('username').value
  $('connect-btn').disabled = state === 'connecting' || state === 'connected'
  $('disconnect-btn').disabled = state === 'idle'

  const live = state === 'connected'
  const pill = $('pill-live')
  pill.classList.toggle('on', live)
  pill.innerHTML = `<i></i> ${live ? 'TIKTOK CANLI' : state === 'connecting' ? 'BAĞLANIYOR' : 'DEMO'}`

  $('side-dot').className = `dot ${state === 'connected' ? 'ok' : state === 'error' ? 'bad' : state === 'connecting' ? 'warn' : ''}`
  $('side-mode').textContent = state === 'connected'
    ? `@${tiktok.username || 'yayıncı'} bağlı`
    : state === 'connecting'
      ? 'Bağlanıyor…'
      : state === 'error'
        ? 'Bağlantı hatası'
        : net.mode === 'socket'
          ? 'Sunucuya bağlı · demo'
          : 'Yerel demo modu'

  if (live) {
    $('kpi-viewers-sub').textContent = `@${tiktok.username || 'tiktok'}`
  }
}

function renderClients() {
  $('pill-clients').innerHTML = `👥 <b>${clients}</b> istemci`
}

/* ------------------------------------------------------------------ metrics */

function renderMetrics() {
  const m = metrics ?? {}
  const players = Array.isArray(m.players) ? m.players : []
  $('kpi-viewers').textContent = compact(tiktok?.viewers || m.viewers || 0)
  $('kpi-viewers-sub').textContent = tiktok?.state === 'connected' ? `@${tiktok.username}` : 'demo yayın'
  const chaos = Math.max(0, Math.min(100, Number(m.chaos) || 0))
  $('kpi-chaos').textContent = `${Math.round(chaos)}%`
  $('kpi-chaos-bar').style.width = `${chaos}%`
  $('kpi-timer').textContent = formatTimer(m.timer ?? settings.roundSeconds)
  $('kpi-state').textContent = m.state === 'paused' ? 'duraklatıldı' : m.state === 'ended' ? 'tur bitti' : 'oyun sürüyor'
  $('kpi-round').textContent = String(m.round ?? 1)
  $('round-tag').textContent = `TUR ${m.round ?? 1}`
  const wins = m.wins ?? {}
  $('kpi-wins').textContent = `Chat ${wins.chat ?? 0} · Çaycı ${wins.cayci ?? 0}`
  const customers = Number(m.customers) || players.filter((p) => p.role === 'musteri').length
  const apprentices = Number(m.apprentices) || players.filter((p) => p.role === 'apprentice').length
  $('kpi-players').textContent = `${customers}/${apprentices}`
  $('kpi-seats').textContent = `${Number(m.seats) || 0}/${Number(m.totalSeats) || 0} masa dolu`
  $('kpi-gifts').textContent = `${compact(m.gifts ?? 0)}/${compact(m.likes ?? 0)}`
  $('kpi-fights').textContent = `${Number(m.fights) || 0} kavga · ${Number(m.spectators) || 0} izleyici`
  renderPlayers(players)
}

function playerStatusLabel(player) {
  const role = player.role
  if (role === 'cayci') return 'Çaycı'
  if (role === 'zabita') return 'Zabıta'
  if (role === 'muhtar') return 'Muhtar'
  if (role === 'apprentice') return `Çırak · ${player.status ?? ''}`
  return player.table != null ? `Masa ${Number(player.table) + 1} · ${player.status ?? ''}` : player.status ?? 'Müşteri'
}

function renderPlayers(players) {
  const list = Array.isArray(players) ? players : []
  const box = $('players')
  $('player-tag').textContent = `${list.length} kişi`
  if (!list.length) {
    box.innerHTML = '<p class="empty">Henüz oyuncu yok. Simülatörden bir olay gönder.</p>'
    return
  }
  box.innerHTML = list.map((p) => {
    const role = String(p.role ?? 'musteri')
    const builtIn = ['cayci', 'zabita', 'muhtar'].includes(role)
    const avatar = p.avatar
      ? `<img src="${esc(p.avatar)}" alt="" loading="lazy" onerror="this.replaceWith(Object.assign(document.createElement('span'),{className:'ph',textContent:'👤'}))" />`
      : `<span class="ph">${role === 'cayci' ? '🫖' : role === 'zabita' ? '🚨' : role === 'muhtar' ? '🎩' : '👤'}</span>`
    const kick = builtIn
      ? ''
      : `<button class="btn danger" data-kick="${esc(p.id)}" title="Meydandan çıkar">Çıkar</button>`
    return `<div class="player">
      ${avatar}
      <div class="player-meta">
        <div class="player-name">${esc(p.nickname || 'izleyici')}</div>
        <div class="player-sub">${esc(playerStatusLabel(p))}</div>
      </div>
      ${kick}
    </div>`
  }).join('')
}

/* ----------------------------------------------------------------- mapping */

function actionOptions(selected, list = ALL_ACTIONS) {
  return list
    .map((id) => `<option value="${id}" ${id === selected ? 'selected' : ''}>${esc(ACTIONS[id]?.title ?? id)}</option>`)
    .join('')
}

function renderActionSelects() {
  $('likes-action').innerHTML = actionOptions(draft.likes, GIFT_ACTIONS)
  $('command-1').innerHTML = actionOptions(draft.commands['1'], COMMAND_ACTIONS)
  $('command-2').innerHTML = actionOptions(draft.commands['2'], COMMAND_ACTIONS)
}

function renderRanges() {
  const box = $('ranges')
  box.innerHTML = draft.ranges.map((range, index) => `
    <div class="range-row" data-index="${index}">
      <input type="number" min="1" max="9999999" value="${range.min}" data-range="min" aria-label="En az jeton" />
      <span class="range-sep">–</span>
      <input type="number" min="1" max="9999999" value="${range.max}" data-range="max" aria-label="En çok jeton" />
      <select data-range="action" aria-label="Aralık aksiyonu">${actionOptions(range.action, GIFT_ACTIONS)}</select>
    </div>
  `).join('')
}

function catalogRows() {
  const byId = new Map()
  for (const gift of catalog) {
    const id = String(gift.id ?? gift.name ?? '')
    if (!id) continue
    byId.set(id, {
      id,
      name: gift.name ?? 'Hediye',
      coins: Number(gift.coins ?? 0),
      emoji: gift.emoji || '🎁',
      image: gift.image || ''
    })
  }
  // Keep overrides that are not in the live catalogue visible.
  for (const id of Object.keys(draft.overrides)) {
    if (!byId.has(id)) byId.set(id, { id, name: `Özel hediye #${id}`, coins: 0, emoji: '🎁', image: '' })
  }
  return [...byId.values()].sort((a, b) => a.coins - b.coins || a.name.localeCompare(b.name, 'tr'))
}

function renderGiftTable() {
  const needle = giftFilter.trim().toLowerCase()
  const rows = catalogRows().filter((gift) =>
    !needle || gift.name.toLowerCase().includes(needle) || String(gift.id).includes(needle)
  )
  const box = $('gift-table')
  if (!rows.length) {
    box.innerHTML = '<p class="empty">Eşleşen hediye yok.</p>'
    return
  }
  box.innerHTML = rows.map((gift) => {
    const override = draft.overrides[gift.id] ?? ''
    const icon = gift.image
      ? `<img src="${esc(gift.image)}" alt="" loading="lazy" onerror="this.replaceWith(Object.assign(document.createElement('span'),{textContent:'${esc(gift.emoji)}'}))" />`
      : esc(gift.emoji)
    return `<div class="gift-row" data-gift-id="${esc(gift.id)}">
      <span class="gift-icon">${icon}</span>
      <span class="gift-name" title="${esc(gift.name)}">${esc(gift.name)}</span>
      <span class="gift-coins">${gift.coins ? `${compact(gift.coins)} ⬤` : '—'}</span>
      <select data-override="${esc(gift.id)}" class="${override ? 'changed' : ''}" aria-label="${esc(gift.name)} aksiyonu">
        <option value="">Aralık kuralı</option>
        ${actionOptions(override, GIFT_ACTIONS)}
      </select>
    </div>`
  }).join('')
}

function setDirty(value = true) {
  dirty = value
  const tag = $('mapping-tag')
  tag.textContent = dirty ? 'KAYDEDİLMEDİ' : 'TEMİZ'
  tag.className = `tag ${dirty ? 'warn' : 'ok'}`
  if (dirty) setSaveNote('Kaydedilmemiş değişiklikler var.', true)
}

function setSaveNote(text, warn = false) {
  const el = $('save-note')
  el.textContent = text
  el.className = `save-note ${warn ? 'warn' : ''}`
  if (text) {
    clearTimeout(setSaveNote.timer)
    setSaveNote.timer = setTimeout(() => {
      if (dirty) return
      el.textContent = ''
    }, 4200)
  }
}

$('likes-action').addEventListener('change', (e) => {
  draft.likes = e.target.value
  setDirty()
})

$('command-1').addEventListener('change', (e) => {
  draft.commands['1'] = e.target.value
  setDirty()
})

$('command-2').addEventListener('change', (e) => {
  draft.commands['2'] = e.target.value
  setDirty()
})

$('ranges').addEventListener('input', (e) => {
  const row = e.target.closest('.range-row')
  if (!row) return
  const range = draft.ranges[Number(row.dataset.index)]
  if (!range) return
  if (e.target.dataset.range === 'min') range.min = Math.max(0, Math.round(Number(e.target.value) || 0))
  if (e.target.dataset.range === 'max') range.max = Math.max(0, Math.round(Number(e.target.value) || 0))
  setDirty()
})

$('ranges').addEventListener('change', (e) => {
  const row = e.target.closest('.range-row')
  if (!row || e.target.dataset.range !== 'action') return
  const range = draft.ranges[Number(row.dataset.index)]
  if (range) range.action = e.target.value
  setDirty()
})

$('gift-table').addEventListener('change', (e) => {
  const id = e.target.dataset.override
  if (!id) return
  if (e.target.value) draft.overrides[id] = e.target.value
  else delete draft.overrides[id]
  e.target.classList.toggle('changed', Boolean(e.target.value))
  setDirty()
})

$('gift-search').addEventListener('input', (e) => {
  giftFilter = e.target.value
  renderGiftTable()
})

$('save-mapping').addEventListener('click', () => {
  const normalized = normalizeMapping(draft)
  savedMapping = normalized
  draft = clone(normalized)
  net.saveMapping(normalized)
  setDirty(false)
  renderActionSelects()
  renderRanges()
  renderGiftTable()
  setSaveNote(net.mode === 'socket' ? 'Kurallar sunucuya kaydedildi.' : 'Kurallar bu tarayıcıya kaydedildi.')
  toast('Hediye kuralları güncellendi.', 'ok')
})

$('reset-mapping').addEventListener('click', () => {
  draft = clone(normalizeMapping(DEFAULT_MAPPING))
  savedMapping = clone(draft)
  net.saveMapping(draft)
  setDirty(false)
  renderActionSelects()
  renderRanges()
  renderGiftTable()
  setSaveNote('Varsayılan kurallar yüklendi.')
  toast('Varsayılan hediye kuralları yüklendi.', 'ok')
})

/* ---------------------------------------------------------------- settings */

const SLIDERS = [
  { key: 'roundSeconds', label: 'Tur süresi', min: 60, max: 1800, step: 10, unit: 'sn' },
  { key: 'chaosTarget', label: 'Kaos hedefi', min: 50, max: 200, step: 5, unit: '%' },
  { key: 'lightIntensity', label: 'Işık şiddeti', min: 0.2, max: 2, step: 0.05, unit: '×' },
  { key: 'bloom', label: 'Bloom', min: 0, max: 2.5, step: 0.05, unit: '' },
  { key: 'fog', label: 'Sis', min: 0, max: 1, step: 0.05, unit: '' },
  { key: 'volume', label: 'Ses seviyesi', min: 0, max: 1, step: 0.05, unit: '' }
]

function renderSliders() {
  $('sliders').innerHTML = SLIDERS.map((s) => {
    const value = Number(settings[s.key] ?? DEFAULT_SETTINGS[s.key])
    const pct = ((value - s.min) / (s.max - s.min)) * 100
    return `<div class="slider">
      <label for="slider-${s.key}"><span>${s.label}</span><output id="out-${s.key}">${value}${s.unit}</output></label>
      <input id="slider-${s.key}" type="range" min="${s.min}" max="${s.max}" step="${s.step}" value="${value}"
        data-setting="${s.key}" style="--fill:${pct}%" />
    </div>`
  }).join('')
}

function renderSettings() {
  $('time-of-day').value = settings.timeOfDay
  $('aspect').value = settings.aspect
  $('auto-demo').checked = Boolean(settings.autoDemo)
}

$('sliders').addEventListener('input', (e) => {
  const key = e.target.dataset.setting
  if (!key) return
  const spec = SLIDERS.find((s) => s.key === key)
  const value = Number(e.target.value)
  settings[key] = value
  const pct = spec ? ((value - spec.min) / (spec.max - spec.min)) * 100 : 50
  e.target.style.setProperty('--fill', `${pct}%`)
  const out = $(`out-${key}`)
  if (out) out.textContent = `${value}${spec?.unit ?? ''}`
  queueSettings({ [key]: value })
})

function queueSettings(patch) {
  settingsEchoUntil = Date.now() + 900
  clearTimeout(settingsTimer)
  settingsTimer = setTimeout(() => {
    settings = net.saveSettings(patch)
    toast('Atmosfer ayarı uygulandı.', 'ok')
  }, 160)
}

$('time-of-day').addEventListener('change', (e) => {
  settings.timeOfDay = e.target.value
  queueSettings({ timeOfDay: e.target.value })
})

$('aspect').addEventListener('change', (e) => {
  settings.aspect = e.target.value
  queueSettings({ aspect: e.target.value })
})

$('auto-demo').addEventListener('change', (e) => {
  settings.autoDemo = e.target.checked
  queueSettings({ autoDemo: e.target.checked })
})

/* ------------------------------------------------------------- connection */

$('connect-form').addEventListener('submit', (e) => {
  e.preventDefault()
  const username = $('username').value.trim().replace(/^@+/, '')
  if (!/^[\w.]{2,64}$/.test(username)) {
    toast('Geçerli bir TikTok kullanıcı adı gir.', 'bad')
    return
  }
  if (net.mode !== 'socket') {
    toast('TikTok bağlantısı için Node sunucusu gerekli. `npm start` ile aç.', 'bad')
    return
  }
  net.emit('admin:connect', { username })
  toast(`@${username} için bağlantı isteniyor…`)
})

$('disconnect-btn').addEventListener('click', () => {
  net.emit('admin:disconnect')
  toast('TikTok bağlantısı kapatılıyor.')
})

/* ----------------------------------------------------------------- rounds */

document.querySelectorAll('[data-round]').forEach((button) => {
  button.addEventListener('click', () => {
    const action = button.dataset.round
    net.emit('admin:round', { action })
    toast(`Tur komutu: ${button.textContent.trim()}`)
  })
})

$('kick-all').addEventListener('click', () => {
  const players = (metrics?.players ?? []).filter((p) => !['cayci', 'zabita', 'muhtar'].includes(p.role))
  if (!players.length) {
    toast('Meydanda çıkarılacak oyuncu yok.')
    return
  }
  for (const player of players) net.emit('admin:kick', { id: player.id })
  toast(`${players.length} oyuncu meydandan çıkarıldı.`, 'ok')
})

$('players').addEventListener('click', (e) => {
  const id = e.target.closest('[data-kick]')?.dataset.kick
  if (!id) return
  net.emit('admin:kick', { id })
  toast('Oyuncu meydandan çıkarıldı.')
})

/* --------------------------------------------------------------- simulator */

const RANDOM_CHATS = ['1', '2', 'çaycı koş!', 'maç başladı', 'çay lütfen', 'bu ne kaos', 'masa boş mu?']

document.querySelectorAll('[data-sim]').forEach((button) => {
  button.addEventListener('click', () => {
    const kind = button.dataset.sim
    const payload = { kind }
    if (kind === 'join') payload.command = button.dataset.command === '2' ? '2' : '1'
    if (kind === 'gift') payload.coins = Number(button.dataset.coins) || 1
    if (kind === 'chat') payload.text = RANDOM_CHATS[Math.floor(Math.random() * RANDOM_CHATS.length)]
    net.emit('admin:simulate', payload)
    toast(`Simülasyon: ${button.textContent.trim()}`, 'ok')
  })
})

$('sim-random').addEventListener('click', () => {
  const roll = Math.random()
  let payload
  if (roll < 0.25) payload = { kind: 'chat', text: RANDOM_CHATS[Math.floor(Math.random() * RANDOM_CHATS.length)] }
  else if (roll < 0.45) payload = { kind: 'like', count: 5 + Math.floor(Math.random() * 40) }
  else if (roll < 0.55) payload = { kind: 'member' }
  else {
    const coins = [1, 5, 10, 20, 30, 49, 100, 249, 300, 1000][Math.floor(Math.random() * 10)]
    payload = { kind: 'gift', coins }
  }
  net.emit('admin:simulate', payload)
  toast(`Rastgele olay: ${payload.kind}`, 'ok')
})

/* -------------------------------------------------------------------- log */

function addLog(kind, label, message, level = '') {
  logCount += 1
  $('log-count').textContent = `${logCount} olay`
  if (logPaused || !message) return
  const li = document.createElement('li')
  li.className = `${kind} ${level}`.trim()
  li.innerHTML = `<time>${formatClock()}</time><span class="kind">${esc(label)}</span><span class="msg">${message}</span>`
  const log = $('log')
  log.prepend(li)
  while (log.children.length > 220) log.lastElementChild.remove()
}

function logGameEvent(event) {
  const user = event.user?.nickname ? `<b>${esc(event.user.nickname)}</b>` : ''
  switch (event.type) {
    case 'chat': {
      const action = event.command ? ACTIONS[event.command]?.title : null
      addLog('chat', 'sohbet', `${user} ${esc(String(event.text ?? '').slice(0, 70))}${action ? ` <em>→ ${esc(action)}</em>` : ''}`)
      break
    }
    case 'gift': {
      const gift = event.gift ?? {}
      const action = event.action ? ACTIONS[event.action]?.title : '—'
      addLog('gift', 'hediye', `${user} <b>${esc(gift.name ?? 'Hediye')}</b> ×${Number(gift.count) || 1} · ${compact(gift.coins ?? 0)} ⬤ <em>→ ${esc(action)}</em>`)
      break
    }
    case 'like':
      addLog('like', 'beğeni', `${user} +${compact(event.count ?? 1)} beğeni${event.total ? ` · toplam ${compact(event.total)}` : ''}`)
      break
    case 'member':
      addLog('member', 'üye', `${user} yayına katıldı`)
      break
    case 'follow':
      addLog('member', 'takip', `${user} takip etti`)
      break
    case 'share':
      addLog('member', 'paylaşım', `${user} yayını paylaştı`)
      break
    default:
      addLog('trace', String(event.type ?? 'olay'), `${user} ${esc(event.text ?? '')}`.trim())
  }
}

$('log-clear').addEventListener('click', () => {
  $('log').innerHTML = ''
  logCount = 0
  $('log-count').textContent = '0 olay'
})

$('log-pause').addEventListener('click', () => {
  logPaused = !logPaused
  $('log-pause').textContent = logPaused ? 'Devam et' : 'Duraklat'
})

/* ------------------------------------------------------------------ toast */

function toast(message, kind = '') {
  const stack = $('toasts')
  const el = document.createElement('div')
  el.className = `toast ${kind}`
  el.textContent = message
  stack.appendChild(el)
  while (stack.children.length > 4) stack.firstElementChild.remove()
  setTimeout(() => el.remove(), 3200)
}

/* ------------------------------------------------------------------- nav */

const sections = [...document.querySelectorAll('main section[id]')]
const links = [...document.querySelectorAll('.nav a')]
if ('IntersectionObserver' in window) {
  const observer = new IntersectionObserver((entries) => {
    for (const entry of entries) {
      if (!entry.isIntersecting) continue
      links.forEach((link) => link.classList.toggle('active', link.getAttribute('href') === `#${entry.target.id}`))
    }
  }, { rootMargin: '-20% 0px -65% 0px' })
  sections.forEach((section) => observer.observe(section))
}

/* ------------------------------------------------------------- initial sync */

renderClients()
setDirty(false)
net.ready.then(() => {
  if (net.socket) requestStateSoon()
})

function requestStateSoon() {
  // The server sends `hello` on connect; ask again after the socket settles so
  // an admin opened after the game still receives the latest metrics.
  setTimeout(() => net.requestState(), 400)
}

window.addEventListener('beforeunload', (event) => {
  if (!dirty) return
  event.preventDefault()
  event.returnValue = ''
})

